    private static final Pattern A_TAG_PATTERN = Pattern.compile(
            "(<a\\s[^>]*href\\s*=\\s*\"([^\"]*)\"[^>]*>)(.*?)(</a>)",
            Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern HTML_TAG_PATTERN = Pattern.compile("<[^>]*>");

    /**
     * Hacker News truncates long links, meaning the visible text of an {@code <a>} tag can end
     * with an ellipsis even though the href points to the complete url. That's fine when reading,
     * but when selecting text you want the full link. This replaces the shortened link text with
     * the actual url it points to.
     */
    public static String expandTruncatedLinks(String html) {
        if (TextUtils.isEmpty(html)) {
            return html;
        }

        Matcher matcher = A_TAG_PATTERN.matcher(html);
        StringBuffer result = new StringBuffer();

        while (matcher.find()) {
            String openingTag = matcher.group(1);
            String href = matcher.group(2);
            String linkText = matcher.group(3);
            String closingTag = matcher.group(4);

            String replacementText = linkText;
            if (!TextUtils.isEmpty(href) && isTruncatedLinkText(linkText, href)) {
                replacementText = TextUtils.htmlEncode(href);
            }

            matcher.appendReplacement(result,
                    Matcher.quoteReplacement(openingTag + replacementText + closingTag));
        }
        matcher.appendTail(result);

        return result.toString();
    }

    private static boolean isTruncatedLinkText(String linkText, String href) {
        if (TextUtils.isEmpty(linkText)) {
            return false;
        }

        // The link text may contain markup (for instance a <span> around the tld), get rid of it
        // and turn html entities (such as the escaped slashes HN uses) into plain characters.
        String plainText = HTML_TAG_PATTERN.matcher(linkText).replaceAll("");
        plainText = Html.fromHtml(plainText).toString().trim();

        String withoutEllipsis;
        if (plainText.endsWith("...")) {
            withoutEllipsis = plainText.substring(0, plainText.length() - 3);
        } else if (plainText.endsWith("\u2026")) {
            withoutEllipsis = plainText.substring(0, plainText.length() - 1);
        } else {
            return false;
        }

        // Only expand when the shown text really is the beginning of the url, we don't want to
        // mess with links where the author wrote their own text
        return !withoutEllipsis.isEmpty()
                && href.regionMatches(true, 0, withoutEllipsis, 0, withoutEllipsis.length());
    }

